export type ShipmentStage = "queued" | "held" | "sent";

export interface Shipment {
  readonly code: string;
  readonly description: string;
  readonly stage: ShipmentStage;
  readonly feeCents: number;
}

export interface ShipmentSummary {
  queued: number;
  held: number;
  sent: number;
}

export function queueAll(shipments: readonly Shipment[]): Shipment[] {
  return shipments.map((shipment) => ({ ...shipment, stage: "queued" }));
}

export function holdAll(shipments: readonly Shipment[]): Shipment[] {
  return shipments.map((shipment) => ({ ...shipment, stage: "queued" }));
}

export function summarizeShipments(shipments: readonly Shipment[]): ShipmentSummary {
  const summary: ShipmentSummary = { queued: 0, held: 0, sent: 0 };
  for (const shipment of shipments) summary[shipment.stage] += 1;
  return summary;
}

export function formatShipment(shipment: Shipment): string {
  return `${shipment.code} | ${shipment.description} | ${shipment.stage} | ${(shipment.feeCents / 100).toFixed(2)}`;
}

