import { queueAll, holdAll, summarizeShipments, formatShipment, Shipment } from './solution';

function equal(actual: unknown, expected: unknown, label: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function ok(condition: boolean, label: string): void {
  if (!condition) throw new Error(label);
}

const first: Shipment = Object.freeze({ code: 'A1', description: 'Alpha', stage: 'sent', feeCents: 1234 });
const second: Shipment = Object.freeze({ code: 'B2', description: 'Beta', stage: 'held', feeCents: 0 });
const third: Shipment = Object.freeze({ code: 'C3', description: 'Credit', stage: 'queued', feeCents: -5 });
const input: readonly Shipment[] = Object.freeze([first, second, third]);

const queued = queueAll(input);
equal(queued, [
  { code: 'A1', description: 'Alpha', stage: 'queued', feeCents: 1234 },
  { code: 'B2', description: 'Beta', stage: 'queued', feeCents: 0 },
  { code: 'C3', description: 'Credit', stage: 'queued', feeCents: -5 },
], 'queue all');
ok(queued !== input, 'queueAll returns a new array');
ok(queued.every((item, index) => item !== input[index]), 'queueAll creates every object');

const held = holdAll(input);
equal(held, [
  { code: 'A1', description: 'Alpha', stage: 'held', feeCents: 1234 },
  { code: 'B2', description: 'Beta', stage: 'held', feeCents: 0 },
  { code: 'C3', description: 'Credit', stage: 'held', feeCents: -5 },
], 'hold all');
ok(held.every((item, index) => item !== input[index]), 'holdAll creates every object');

equal(input, [first, second, third], 'bulk operations do not mutate input array');
equal(first, { code: 'A1', description: 'Alpha', stage: 'sent', feeCents: 1234 }, 'bulk operations do not mutate objects');

equal(summarizeShipments(input), { queued: 1, held: 1, sent: 1 }, 'summary counts');
equal(summarizeShipments([]), { queued: 0, held: 0, sent: 0 }, 'summary includes zero counters');

ok(formatShipment(first) === 'A1 | Alpha | sent | 12.34', 'positive fee formatting');
ok(formatShipment(second) === 'B2 | Beta | held | 0.00', 'zero fee formatting');
ok(formatShipment(third) === 'C3 | Credit | queued | -0.05', 'negative fee formatting');

const queueEmptyA = queueAll([]);
const queueEmptyB = queueAll([]);
const holdEmpty = holdAll([]);
equal(queueEmptyA, [], 'empty queue result');
equal(holdEmpty, [], 'empty hold result');
ok(queueEmptyA !== queueEmptyB && queueEmptyA !== holdEmpty, 'empty arrays are freshly allocated');

